/*
 * Lexi Loader - Reseller Panel Backend
 * Merged backend with full loader/session management, audit logs, file manifests, and neon panel features.
 */

const express = require("express");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const app = express();
if (process.env.LEXI_TRUST_PROXY === "1") app.set("trust proxy", 1);
const PORT = Number(process.env.PORT || 3000);
const DB_FILE = path.join(__dirname, "database.json");
const DB_LOCK_FILE = `${DB_FILE}.lock`;
let dbLockHeld = false;
function acquireDatabaseLock() {
  try {
    const fd = fs.openSync(DB_LOCK_FILE, "wx", 0o600);
    fs.writeFileSync(fd, JSON.stringify({ pid: process.pid, startedAt: now() }));
    fs.closeSync(fd);
    dbLockHeld = true;
  } catch (err) {
    if (err.code === "EEXIST") {
      try {
        const lock = JSON.parse(fs.readFileSync(DB_LOCK_FILE, "utf8"));
        let alive = false;
        if (Number.isInteger(lock.pid) && lock.pid > 0) { try { process.kill(lock.pid, 0); alive = true; } catch {} }
        if (!alive) { fs.unlinkSync(DB_LOCK_FILE); return acquireDatabaseLock(); }
      } catch {}
    }
    throw new Error(`Database is already in use or its lock cannot be acquired: ${err.message}`);
  }
}
function releaseDatabaseLock() {
  if (!dbLockHeld) return;
  try { fs.unlinkSync(DB_LOCK_FILE); } catch {}
  dbLockHeld = false;
}

app.disable("x-powered-by");
app.use((req,res,next)=>{
  res.setHeader("Cache-Control","no-store");
  res.setHeader("X-Content-Type-Options","nosniff");
  res.setHeader("X-Frame-Options","DENY");
  res.setHeader("Referrer-Policy","no-referrer");
  res.setHeader("Permissions-Policy","camera=(), microphone=(), geolocation=()");
  res.setHeader("Content-Security-Policy", "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'");
  if (process.env.NODE_ENV === "production") res.setHeader("Strict-Transport-Security","max-age=31536000; includeSubDomains");
  next();
});
app.use(express.json({ limit: "256kb" }));
app.use(express.urlencoded({ extended: false, limit: "64kb" }));

app.use((req, res, next) => {
  const supplied = String(req.headers["x-request-id"] || "").trim();
  const requestId = /^[A-Za-z0-9._:-]{8,80}$/.test(supplied) ? supplied : randomId("req");
  req.requestId = requestId;
  res.setHeader("X-Request-ID", requestId);
  next();
});

const DEFAULT_SESSION_TIMEOUT_MS = 30 * 24 * 60 * 60 * 1000;
const ALLOWED_SESSION_HOURS = [720];
const RESET_WINDOW_MS = 24 * 60 * 60 * 1000;
const MAX_RESET_ATTEMPTS = 3;
const MAX_PANEL_DEVICE_RESETS = 3;
function resetWindowForRole(role) {
  if (role === ROLE.ADMIN) return 7 * 24 * 60 * 60 * 1000;
  if (role === ROLE.RESELLER) return 30 * 24 * 60 * 60 * 1000;
  return 24 * 60 * 60 * 1000;
}
function resetWindowLabel(role) {
  if (role === ROLE.ADMIN) return "7 days";
  if (role === ROLE.RESELLER) return "30 days";
  return "24 hours";
}
const LOGIN_WINDOW_MS = 15 * 60 * 1000;
const MAX_LOGIN_FAILURES = 10;
const MAX_LOGIN_FAILURES_PER_IP = 40;
const loginIpFailures = new Map();
function allowLoginIp(ip) {
  const t = Date.now(); const row = loginIpFailures.get(ip) || { started: t, count: 0 };
  if (t - row.started >= LOGIN_WINDOW_MS) { row.started = t; row.count = 0; }
  if (row.count >= MAX_LOGIN_FAILURES_PER_IP) return false;
  row.count++; loginIpFailures.set(ip, row); return true;
}
const MAX_KEY_QUANTITY = 1000;
const MAX_DEVICE_LIMIT = 9999;
const LOADER_SESSION_TTL_MS = 30 * 60 * 1000;
const LOADER_MAX_BODY = 32 * 1024;
const LOADER_API_VERSION = 1;
const DEFAULT_LOADER_VERSION = "1.0.0";
const DEFAULT_TARGET_PACKAGE = "com.pubg.imobile";

const ROLE = Object.freeze({ OWNER: "owner", ADMIN: "admin", RESELLER: "reseller" });
const STATUS = Object.freeze({ ACTIVE: "active", BLOCKED: "blocked", DELETED: "deleted" });
const KEY_STATUS = Object.freeze({ ACTIVE: "active", BLOCKED: "blocked", EXPIRED: "expired", DELETED: "deleted" });

const PRICING = Object.freeze({
  "3h":  { label: "3 Hour", hours: 3,   price: 10 },
  "1d":  { label: "1 Day",   hours: 24,  price: 100 },
  "3d":  { label: "3 Days",  hours: 72,  price: 200 },
  "7d":  { label: "7 Days",  hours: 168, price: 350 },
  "15d": { label: "15 Days", hours: 360, price: 500 },
  "30d": { label: "30 Days", hours: 720, price: 750 },
  "60d": { label: "60 Days", hours: 1440, price: 1000 }
});

function now() { return new Date().toISOString(); }
function randomId(prefix) { return `${prefix}_${crypto.randomBytes(10).toString("hex")}`; }
function randomToken(bytes = 32) { return crypto.randomBytes(bytes).toString("hex"); }
function hashPanelToken(token) { return crypto.createHash("sha256").update(String(token)).digest("hex"); }
function normalizeUsername(value) { return String(value || "").trim().toLowerCase(); }
function normalizeCode(value) { return String(value || "").trim().toUpperCase(); }
function sanitizeString(value, max = 200) { return String(value ?? "").trim().slice(0, max); }
function clientIp(req) { return String(req.ip || req.socket.remoteAddress || "unknown"); }
function clientCountry(req) {
  if (process.env.LEXI_TRUST_COUNTRY_HEADER !== "1") return "";
  return String(req.headers["x-country-code"] || "").trim().toUpperCase();
}

function enforceGeoLock(req, expectedCountry) {
  const expected = String(expectedCountry || "").trim().toUpperCase();
  if (!expected) return null;
  const country = clientCountry(req);
  if (!country) return { status: 503, code: "GEO_UNAVAILABLE", message: "Geo verification is not configured." };
  if (country !== expected) return { status: 403, code: "GEO_LOCKED", message: "Geo Locked" };
  return null;
}

function parseCookies(req) {
  const raw = String(req.headers.cookie || "");
  const out = {};
  for (const part of raw.split(";")) {
    const i = part.indexOf("=");
    if (i < 0) continue;
    const k = part.slice(0, i).trim();
    let v = part.slice(i + 1).trim();
    try { v = decodeURIComponent(v); } catch { continue; }
    if (k) out[k] = v;
  }
  return out;
}

function setNamedSessionCookie(res, name, token, maxAgeMs) {
  const maxAge = Math.max(1, Math.floor(maxAgeMs / 1000));
  return `${name}=${encodeURIComponent(token)}; Max-Age=${maxAge}; Path=/; HttpOnly; SameSite=Lax${process.env.NODE_ENV === "production" ? "; Secure" : ""}`;
}
function setSessionCookie(res, token, maxAgeMs) {
  res.setHeader("Set-Cookie", setNamedSessionCookie(res, "lexi_session", token, maxAgeMs));
}
function setOwnerSessionCookie(res, sessionId) {
  res.append("Set-Cookie", setNamedSessionCookie(res, "lexi_owner_session", sessionId, DEFAULT_SESSION_TIMEOUT_MS));
}
function clearOwnerSessionCookie(res) {
  res.append("Set-Cookie", `lexi_owner_session=; Max-Age=0; Path=/; HttpOnly; SameSite=Lax${process.env.NODE_ENV === "production" ? "; Secure" : ""}`);
}

function clearSessionCookie(res) {
  res.setHeader("Set-Cookie", `lexi_session=; Max-Age=0; Path=/; HttpOnly; SameSite=Lax${process.env.NODE_ENV === "production" ? "; Secure" : ""}`);
}

function safeEqual(a, b) {
  const aa = Buffer.from(String(a));
  const bb = Buffer.from(String(b));
  return aa.length === bb.length && crypto.timingSafeEqual(aa, bb);
}

function hashPasswordSync(password) {
  const salt = crypto.randomBytes(16).toString("hex");
  const derived = crypto.scryptSync(String(password), salt, 64).toString("hex");
  return `scrypt$${salt}$${derived}`;
}
function hashPassword(password) {
  return new Promise((resolve, reject) => {
    const salt = crypto.randomBytes(16).toString("hex");
    crypto.scrypt(String(password), salt, 64, (err, derived) => {
      if (err) return reject(err);
      resolve(`scrypt$${salt}$${derived.toString("hex")}`);
    });
  });
}
function verifyPassword(password, storedHash) {
  return new Promise(resolve => {
    try {
      const parts = String(storedHash).split("$");
      if (parts.length !== 3 || parts[0] !== "scrypt") return resolve(false);
      const [, salt, expected] = parts;
      crypto.scrypt(String(password), salt, 64, (err, derived) => {
        if (err) return resolve(false);
        resolve(safeEqual(derived.toString("hex"), expected));
      });
    } catch { resolve(false); }
  });
}

function initialDatabase() {
  return {
    version: 6,
    settings: {
      loaderStatus: true,
      maintenanceMsg: "Loader is temporarily under maintenance.",
      panelName: "Lexi Loader",
      supportLink: "",
      ipGeoLockEnabled: false,
      sessionTimeoutHours: 720,
      resetLimit: 3,
      resetWindowHours: 24,
      systemOnline: true,
      onlineMessage: "System is online.",
      appNotice: "",
      appNoticeType: "info",
      appNoticeEnabled: false,
      loaderApiVersion: LOADER_API_VERSION,
      loaderVersion: DEFAULT_LOADER_VERSION,
      loaderMinimumVersion: DEFAULT_LOADER_VERSION,
      loaderTargetPackage: DEFAULT_TARGET_PACKAGE,
      loaderUpdateUrl: "",
      loaderUpdateSha256: "",
      loaderUpdateSize: 0,
      loaderUpdateRequired: false,
      loaderUpdateNotes: "",
      loaderFeatures: { BT: true, AIM: true, ESP: true, IPAD_VIEW: true },
      loaderFileManifests: [],
      createdAt: now(),
      updatedAt: now()
    },
    pricing: { ...PRICING },
    users: [], referrals: [], keys: [], devices: [], transactions: [], auditLogs: [], sessions: [], loaderSessions: [], rateLimits: []
  };
}

function loadDb() {
  if (!fs.existsSync(DB_FILE)) {
    const db = initialDatabase();
    atomicWrite(db);
    return db;
  }
  try {
    const raw = fs.readFileSync(DB_FILE, "utf8");
    const db = JSON.parse(raw);
    const base = initialDatabase();
    return {
      ...base, ...db,
      settings: { ...base.settings, ...(db.settings || {}) },
      pricing: { ...base.pricing, ...(db.pricing || {}) },
      users: db.users === undefined ? [] : (Array.isArray(db.users) ? db.users : (()=>{throw new Error("database.json users must be an array")})()),
      referrals: db.referrals === undefined ? [] : (Array.isArray(db.referrals) ? db.referrals : (()=>{throw new Error("database.json referrals must be an array")})()),
      keys: db.keys === undefined ? [] : (Array.isArray(db.keys) ? db.keys : (()=>{throw new Error("database.json keys must be an array")})()),
      devices: db.devices === undefined ? [] : (Array.isArray(db.devices) ? db.devices : (()=>{throw new Error("database.json devices must be an array")})()),
      transactions: db.transactions === undefined ? [] : (Array.isArray(db.transactions) ? db.transactions : (()=>{throw new Error("database.json transactions must be an array")})()),
      auditLogs: db.auditLogs === undefined ? [] : (Array.isArray(db.auditLogs) ? db.auditLogs : (()=>{throw new Error("database.json auditLogs must be an array")})()),
      sessions: db.sessions === undefined ? [] : (Array.isArray(db.sessions) ? db.sessions : (()=>{throw new Error("database.json sessions must be an array")})()),
      loaderSessions: db.loaderSessions === undefined ? [] : (Array.isArray(db.loaderSessions) ? db.loaderSessions : (()=>{throw new Error("database.json loaderSessions must be an array")})()),
      rateLimits: db.rateLimits === undefined ? [] : (Array.isArray(db.rateLimits) ? db.rateLimits : (()=>{throw new Error("database.json rateLimits must be an array")})())
    };
  } catch (err) {
    throw new Error(`database.json is invalid: ${err.message}`);
  }
}

function migrateDatabase() {
  db.version = 6;
  db.settings = db.settings || {};
  if (!db.settings.loaderTargetPackage) db.settings.loaderTargetPackage = DEFAULT_TARGET_PACKAGE;
  if (db.settings.maintenanceMessage !== undefined && db.settings.maintenanceMsg === undefined) db.settings.maintenanceMsg = db.settings.maintenanceMessage;
  if (db.settings.supportUrl !== undefined && db.settings.supportLink === undefined) db.settings.supportLink = db.settings.supportUrl;
  if (db.settings.optionalIpLock !== undefined && db.settings.ipGeoLockEnabled === undefined) db.settings.ipGeoLockEnabled = Boolean(db.settings.optionalIpLock);
  if (db.settings.sessionTimeoutHours === undefined || !ALLOWED_SESSION_HOURS.includes(Number(db.settings.sessionTimeoutHours))) db.settings.sessionTimeoutHours = 720;
  if (db.settings.resetLimit === undefined) db.settings.resetLimit = 3;
  if (db.settings.resetWindowHours === undefined) db.settings.resetWindowHours = 24;
  if (db.settings.systemOnline === undefined) db.settings.systemOnline = true;
  if (db.settings.onlineMessage === undefined) db.settings.onlineMessage = "System is online.";
  if (db.settings.appNotice === undefined) db.settings.appNotice = "";
  if (db.settings.appNoticeType === undefined) db.settings.appNoticeType = "info";
  if (db.settings.appNoticeEnabled === undefined) db.settings.appNoticeEnabled = false;
  if (db.settings.loaderApiVersion === undefined) db.settings.loaderApiVersion = LOADER_API_VERSION;
  if (db.settings.loaderVersion === undefined) db.settings.loaderVersion = DEFAULT_LOADER_VERSION;
  if (db.settings.loaderMinimumVersion === undefined) db.settings.loaderMinimumVersion = DEFAULT_LOADER_VERSION;
  if (db.settings.loaderUpdateUrl === undefined) db.settings.loaderUpdateUrl = "";
  if (db.settings.loaderUpdateSha256 === undefined) db.settings.loaderUpdateSha256 = "";
  if (db.settings.loaderUpdateSize === undefined) db.settings.loaderUpdateSize = 0;
  if (db.settings.loaderUpdateRequired === undefined) db.settings.loaderUpdateRequired = false;
  if (db.settings.loaderUpdateNotes === undefined) db.settings.loaderUpdateNotes = "";
  if (!db.settings.loaderFeatures || typeof db.settings.loaderFeatures !== "object") db.settings.loaderFeatures = { BT: true, AIM: true, ESP: true, IPAD_VIEW: true };
  if (!Array.isArray(db.settings.loaderFileManifests)) db.settings.loaderFileManifests = [];
  if (!Array.isArray(db.loaderSessions)) db.loaderSessions = [];
  db.pricing = { ...PRICING, ...(db.pricing || {}) };
  for (const session of db.sessions || []) {
    if (!session.tokenHash && session.token) { session.tokenHash = hashPanelToken(session.token); delete session.token; }
  }
  for (const u of db.users) {
    if (u.role === "user" || u.role === "normal" || u.role === "limited") u.role = ROLE.RESELLER;
    if (!u.registeredIp) u.registeredIp = null;
    if (!u.passwordResetAttempts) u.passwordResetAttempts = 0;
    if (!u.passwordResetWindowStartedAt) u.passwordResetWindowStartedAt = now();
    if (!Number.isInteger(u.usernameChangeCount)) u.usernameChangeCount = 0;
    if (!Number.isInteger(u.panelDeviceResetCount)) u.panelDeviceResetCount = 0;
    if (u.panelDeviceId === undefined) u.panelDeviceId = null;
  }
  for (const k of db.keys) {
    if (k.startedAt === undefined) {
      if (k.expiryAt && k.durationHours) {
        const expiryMs = Date.parse(k.expiryAt);
        const durationMs = Number(k.durationHours) * 60 * 60 * 1000;
        k.startedAt = Number.isFinite(expiryMs) ? new Date(expiryMs - durationMs).toISOString() : null;
      } else k.startedAt = null;
    }
    if (k.expiryAt === undefined) k.expiryAt = null;
    if (k.active_hack === undefined) k.active_hack = "ESP";
    if (k.hack_expiry === undefined) k.hack_expiry = null;
  }
}

function atomicWrite(db) {
  const tmp = `${DB_FILE}.${process.pid}.tmp`;
  const data = JSON.stringify(db, null, 2);
  const fd = fs.openSync(tmp, "w", 0o600);
  try { fs.writeFileSync(fd, data, "utf8"); fs.fsyncSync(fd); } finally { fs.closeSync(fd); }
  fs.renameSync(tmp, DB_FILE);
}

acquireDatabaseLock();
let db = loadDb();
const dbBeforeMigration = JSON.stringify(db);
migrateDatabase();
if (JSON.stringify(db) !== dbBeforeMigration) { try { atomicWrite(db); } catch (err) { console.error("[Lexi Loader] migration persistence failed:", err.message); } }

function save() {
  db.settings.updatedAt = now();
  try { atomicWrite(db); } catch (err) {
    console.error("[Lexi Loader] FATAL persistence failure:", err);
    process.exitCode = 1;
    releaseDatabaseLock();
    process.exit(1);
  }
}

function publicUser(user) {
  return {
    id: user.id, username: user.username, role: user.role, status: user.status, parentId: user.parentId, balance: Number(user.balance || 0), createdAt: user.createdAt, lastLoginAt: user.lastLoginAt || null,
    reset: { used: Number(user.resetAttempts || 0), remaining: Math.max(0, MAX_RESET_ATTEMPTS - Number(user.resetAttempts || 0)), windowStartedAt: user.resetWindowStartedAt || null },
    panelDevice: { bound: Boolean(user.panelDeviceId), resetUsed: Number(user.panelDeviceResetCount || 0), resetRemaining: Math.max(0, MAX_PANEL_DEVICE_RESETS - Number(user.panelDeviceResetCount || 0)) }
  };
}

function findUserByUsername(username) { const normalized = normalizeUsername(username); return db.users.find(u => normalizeUsername(u.username) === normalized); }
function findUserById(id) { return db.users.find(u => u.id === id); }
function isActiveUser(user) { return !!user && user.status === STATUS.ACTIVE; }
function isDescendantOrSelf(targetUserId, actorUserId) {
  if (targetUserId === actorUserId) return true;
  let current = findUserById(targetUserId);
  const seen = new Set();
  while (current && current.parentId && !seen.has(current.id)) {
    seen.add(current.id);
    if (current.parentId === actorUserId) return true;
    current = findUserById(current.parentId);
  }
  return false;
}
function canManageUser(actor, target) {
  if (!actor || !target) return false;
  if (actor.role === ROLE.OWNER) return actor.id !== target.id;
  if (actor.role === ROLE.ADMIN) return target.role === ROLE.RESELLER && isDescendantOrSelf(target.id, actor.id) && target.id !== actor.id;
  return false;
}
function canViewUser(actor, target) {
  if (!actor || !target) return false;
  if (actor.role === ROLE.OWNER) return true;
  if (actor.role === ROLE.ADMIN) return target.id === actor.id || isDescendantOrSelf(target.id, actor.id);
  return target.id === actor.id;
}
function canManageKey(actor, key) {
  if (!actor || !key) return false;
  if (actor.role === ROLE.OWNER) return true;
  if (key.creatorId === actor.id) return true;
  if (actor.role === ROLE.ADMIN) {
    const creator = findUserById(key.creatorId);
    return !!creator && isDescendantOrSelf(creator.id, actor.id);
  }
  return false;
}
function keyStatus(key) {
  if (key.status === KEY_STATUS.DELETED) return KEY_STATUS.DELETED;
  if (key.status === KEY_STATUS.BLOCKED) return KEY_STATUS.BLOCKED;
  if (key.startedAt && key.expiryAt && Date.now() >= Date.parse(key.expiryAt)) return KEY_STATUS.EXPIRED;
  return KEY_STATUS.ACTIVE;
}
function publicKey(key) {
  const devices = db.devices.filter(d => d.keyId === key.id);
  return {
    id: key.id, key: key.key, creatorId: key.creatorId, creatorUsername: findUserById(key.creatorId)?.username || null, duration: key.duration, durationLabel: key.durationLabel, deviceLimit: key.deviceLimit, quantityBatchId: key.batchId || null, createdAt: key.createdAt, startedAt: key.startedAt || null, expiryAt: key.expiryAt || null, activated: !!key.startedAt, hwid: devices[0]?.hwid || null, status: keyStatus(key), gamePackage: key.gamePackage || "", ipLock: key.ipLock || null, geoLock: key.geoLock || null, devicesUsed: devices.length, active_hack: key.active_hack || "ESP", hack_expiry: key.hack_expiry || null,
    devices: devices.map(d => ({ id: d.id, hwid: d.hwid, deviceName: d.deviceName || "", ip: d.ip || "", firstSeenAt: d.firstSeenAt, lastSeenAt: d.lastSeenAt })), deletedAt: key.deletedAt || null
  };
}

function audit(actor, action, targetType, targetId, details = {}) {
  db.auditLogs.push({ id: randomId("audit"), actorId: actor?.id || "system", actorUsername: actor?.username || "system", action, targetType, targetId: targetId || null, ip: details.ip || null, details: details.details || {}, createdAt: now() });
  if (db.auditLogs.length > 10000) db.auditLogs.splice(0, db.auditLogs.length - 10000);
}
function transaction(actor, type, amount, before, after, targetUserId, details = {}) {
  db.transactions.push({ id: randomId("txn"), type, amount: Number(amount), balanceBefore: Number(before), balanceAfter: Number(after), actorId: actor?.id || "system", actorUsername: actor?.username || "system", targetUserId, details, createdAt: now() });
  if (db.transactions.length > 20000) db.transactions.splice(0, db.transactions.length - 20000);
}

function cleanRateLimits() {
  const cutoffMs = Date.now() - LOGIN_WINDOW_MS;
  for (const [ip,row] of loginIpFailures) if (row.started < cutoffMs) loginIpFailures.delete(ip);
  const cutoff = Date.now() - Math.max(LOGIN_WINDOW_MS, RESET_WINDOW_MS);
  db.rateLimits = db.rateLimits.filter(x => Date.parse(x.updatedAt || x.createdAt || 0) >= cutoff);
}
function failedLoginCount(ip, username) {
  cleanRateLimits();
  const row = db.rateLimits.find(x => x.type === "login" && x.ip === ip && x.username === username);
  if (!row) return 0;
  if (Date.now() - Date.parse(row.windowStartedAt) > LOGIN_WINDOW_MS) return 0;
  return Number(row.failures || 0);
}
function registerFailedLogin(ip, username) {
  cleanRateLimits();
  let row = db.rateLimits.find(x => x.type === "login" && x.ip === ip && x.username === username);
  if (!row || Date.now() - Date.parse(row.windowStartedAt) > LOGIN_WINDOW_MS) {
    row = { id: randomId("rate"), type: "login", ip, username, failures: 0, windowStartedAt: now(), createdAt: now(), updatedAt: now() };
    db.rateLimits.push(row);
  }
  row.failures += 1; row.updatedAt = now(); save(); return row.failures;
}
function clearFailedLogin(ip, username) {
  db.rateLimits = db.rateLimits.filter(x => !(x.type === "login" && x.ip === ip && x.username === username));
  save();
}

function createSession(user, req, rememberMe = false, supportSession = false, sessionTimeoutHours = null) {
  const token = randomToken(32);
  const created = Date.now();
  const timeoutHours = 720;
  const maxAge = DEFAULT_SESSION_TIMEOUT_MS;

  db.sessions.push({ id: randomId("session"), tokenHash: hashPanelToken(token), userId: user.id, createdAt: new Date(created).toISOString(), lastActivityAt: new Date(created).toISOString(), expiresAt: new Date(created + maxAge).toISOString(), ip: clientIp(req), userAgent: String(req.headers["user-agent"] || "").slice(0, 300), rememberMe: !!rememberMe, supportSession: !!supportSession, timeoutHours });
  return token;
}

function getSession(req) {
  const header = String(req.headers.authorization || "");
  let token = header.startsWith("Bearer ") ? header.slice(7).trim() : "";
  if (!token) token = parseCookies(req).lexi_session || "";
  if (!token) return null;

  const tokenHash = hashPanelToken(token);
  const session = db.sessions.find(s => s.tokenHash ? safeEqual(s.tokenHash, tokenHash) : safeEqual(s.token, token));
  if (!session) return null;
  if (Date.now() >= Date.parse(session.expiresAt)) {
    db.sessions = db.sessions.filter(s => s.id !== session.id); save(); return null;
  }
  const user = findUserById(session.userId);
  if (!isActiveUser(user)) return null;
  const activityMs = Date.parse(session.lastActivityAt || 0);
  if (!Number.isFinite(activityMs) || Date.now() - activityMs >= 5 * 60 * 1000) {
    session.lastActivityAt = now();
    session.expiresAt = new Date(Date.now() + DEFAULT_SESSION_TIMEOUT_MS).toISOString();
    save();
  }
  return { session, user, token };
}

function auth(req, res, next) {
  const result = getSession(req);
  if (!result) return res.status(401).json({ success: false, message: "Authentication required." });
  req.user = result.user; req.session = result.session;
  setSessionCookie(res, result.token, Math.max(1, Date.parse(result.session.expiresAt) - Date.now()));
  next();
}
function requireRoles(...roles) {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) return res.status(403).json({ success: false, message: "Permission denied." });
    next();
  };
}

function resetWindow(user) {
  if (!user.resetWindowStartedAt || Date.now() - Date.parse(user.resetWindowStartedAt) >= RESET_WINDOW_MS) {
    user.resetAttempts = 0; user.resetWindowStartedAt = now();
  }
}
function validUsername(username) { return /^[a-zA-Z0-9_.-]{3,32}$/.test(username); }
function validPassword(password) { return typeof password === "string" && password.length >= 6 && password.length <= 128; }
function normalizeRole(role) {
  const value = String(role || "").toLowerCase();
  if (value === ROLE.OWNER) return ROLE.OWNER;
  if (value === ROLE.ADMIN) return ROLE.ADMIN;
  return ROLE.RESELLER;
}
function randomKeyTail() {
  const length = 15 + crypto.randomInt(11);
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const numbers = "0123456789";
  let out = "";
  for (let i = 0; i < length; i++) {
    const useNumber = crypto.randomInt(100) < 25;
    const chars = useNumber ? numbers : alphabet;
    out += chars[crypto.randomInt(chars.length)];
  }
  return out;
}
function durationKeyLabel(duration, durationLabel) {
  const d = String(duration || "").toLowerCase();
  if (/^\d+h$/.test(d)) return d.toUpperCase();
  if (/^\d+d$/.test(d)) return d.toUpperCase();
  const match = String(durationLabel || "").match(/(\d+)\s*(hour|hours|day|days)/i);
  if (match) return Number(match[1]) + (match[2].toLowerCase().startsWith("h") ? "H" : "D");
  return "CUSTOM";
}
function generateLicenseKey(prefix = "Lexi-Loader", duration = "", durationLabel = "") {
  const cleanPrefix = String(prefix || "Lexi-Loader").replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 20) || "Lexi-Loader";
  return `${cleanPrefix}_${durationKeyLabel(duration, durationLabel)}_${randomKeyTail()}`;
}
function ensureUniqueKey(prefix, duration, durationLabel) {
  for (let attempt = 0; attempt < 100; attempt++) {
    const key = generateLicenseKey(prefix, duration, durationLabel);
    if (!db.keys.some(k => k.key === key)) return key;
  }
  throw new Error("Unable to generate a unique license key after 100 attempts.");
}
function getCreatorKeyScope(actor) {
  if (actor.role === ROLE.OWNER) return () => true;
  if (actor.role === ROLE.ADMIN) { return k => { const creator = findUserById(k.creatorId); return !!creator && isDescendantOrSelf(creator.id, actor.id); }; }
  return k => k.creatorId === actor.id;
}

function ensureOwner() {
  if (db.users.length > 0) return;
  if (!process.env.LEXI_OWNER_PASSWORD) throw new Error("LEXI_OWNER_PASSWORD must be configured before first owner initialization.");
  const ownerPassword = process.env.LEXI_OWNER_PASSWORD;
  const owner = { id: randomId("usr"), username: process.env.LEXI_OWNER_USERNAME || "owner", passwordHash: hashPasswordSync(ownerPassword), role: ROLE.OWNER, status: STATUS.ACTIVE, parentId: null, balance: 0, resetAttempts: 0, resetWindowStartedAt: now(), passwordResetAttempts: 0, passwordResetWindowStartedAt: now(), createdAt: now(), lastLoginAt: null };
  db.users.push(owner);
  audit(owner, "OWNER_INITIALIZED", "user", owner.id, { details: { username: owner.username } });
  save();
}
ensureOwner();

/* ---------- APIs ---------- */
app.get("/api/health", (req, res) => { res.json({ success: true, service: "Lexi Loader Backend", version: db.version, time: now() }); });

app.post("/api/auth/login", async (req, res) => {
  const username = normalizeUsername(req.body.username);
  const password = String(req.body.password || "");
  const rememberMe = Boolean(req.body.rememberMe);
  const requestedSessionHours = Number(req.body.sessionTimeoutHours || 720);
  const sessionTimeoutHours = ALLOWED_SESSION_HOURS.includes(requestedSessionHours) ? requestedSessionHours : 720;
  const ip = clientIp(req);

  if (!username || !password) return res.status(400).json({ success: false, message: "Username and password are required." });
  if (!allowLoginIp(ip) || failedLoginCount(ip, username) >= MAX_LOGIN_FAILURES) return res.status(429).json({ success: false, message: "Too many failed login attempts. Please try again later." });

  const user = findUserByUsername(username);
  if (!user || !(await verifyPassword(password, user.passwordHash))) {
    registerFailedLogin(ip, username);
    return res.status(401).json({ success: false, message: "Invalid username or password." });
  }
  if (user.status !== STATUS.ACTIVE) return res.status(401).json({ success: false, message: "Invalid username or password." });

  const panelDeviceId = sanitizeString(req.body.deviceId || "", 160);
  if (user.role !== ROLE.OWNER) {
    const deviceMismatch = Boolean(user.panelDeviceId && panelDeviceId && user.panelDeviceId !== panelDeviceId);
    const ipMismatch = Boolean(user.panelIp && user.panelIp !== ip);
    if (deviceMismatch || ipMismatch) {
      return res.status(403).json({ success: false, code: "DEVICE_LIMIT_REACHED", message: "Device Limit Reached", resetAvailable: Number(user.panelDeviceResetCount || 0) < MAX_PANEL_DEVICE_RESETS, resetRemaining: Math.max(0, MAX_PANEL_DEVICE_RESETS - Number(user.panelDeviceResetCount || 0)) });
    }
    if (!user.panelDeviceId && panelDeviceId) user.panelDeviceId = panelDeviceId;
    if (!user.panelIp) user.panelIp = ip;
    db.sessions = db.sessions.filter(s => s.userId !== user.id);
  }

  clearFailedLogin(ip, username);
  user.lastLoginAt = now();
  const token = createSession(user, req, rememberMe, false, sessionTimeoutHours);
  const sessionMaxAge = DEFAULT_SESSION_TIMEOUT_MS;
  setSessionCookie(res, token, sessionMaxAge);
  audit(user, "LOGIN", "user", user.id, { ip, details: { rememberMe } });
  save();
  res.json({ success: true, user: publicUser(user), session: { timeoutHours: 720, rememberMe: false } });
});

app.post("/api/auth/logout", auth, (req, res) => {
  db.sessions = db.sessions.filter(s => s.id !== req.session.id);
  clearSessionCookie(res);
  audit(req.user, "LOGOUT", "user", req.user.id, { ip: clientIp(req) });
  save(); res.json({ success: true, message: "Logged out successfully." });
});

app.get("/api/auth/me", auth, (req, res) => { res.json({ success: true, user: publicUser(req.user), supportSession: Boolean(req.session.supportSession) }); });

app.post("/api/auth/register", async (req, res) => {
  const username = normalizeUsername(req.body.username); const password = String(req.body.password || ""); const referralCode = normalizeCode(req.body.referralCode); const ip = clientIp(req);
  if (!validUsername(username)) return res.status(400).json({ success: false, message: "Invalid username." });
  if (!validPassword(password)) return res.status(400).json({ success: false, message: "Invalid password." });
  if (!referralCode) return res.status(400).json({ success: false, message: "Referral code required." });
  if (findUserByUsername(username)) return res.status(409).json({ success: false, message: "Username exists." });
  const referral = db.referrals.find(r => normalizeCode(r.code) === referralCode);
  if (!referral || referral.status !== STATUS.ACTIVE) return res.status(400).json({ success: false, message: "Invalid code." });
  if (Number(referral.usageLimit || 0) > 0 && Number(referral.usedCount || 0) >= Number(referral.usageLimit)) return res.status(400).json({ success: false, message: "Referral usage limit reached." });
  if (referral.expiresAt && Date.now() >= Date.parse(referral.expiresAt)) { referral.status = STATUS.BLOCKED; save(); return res.status(400).json({ success: false, message: "Code expired." }); }
  const creator = findUserById(referral.creatorId);
  if (!creator || creator.status !== STATUS.ACTIVE) return res.status(400).json({ success: false, message: "Referral owner unavailable." });
  const assignedRole = normalizeRole(referral.role);
  if (creator.role === ROLE.ADMIN && assignedRole !== ROLE.RESELLER) return res.status(400).json({ success: false, message: "Invalid role." });
  if (creator.role === ROLE.RESELLER) return res.status(400).json({ success: false, message: "Resellers cannot refer." });

  const user = { id: randomId("usr"), username, passwordHash: await hashPassword(password), role: assignedRole, status: STATUS.ACTIVE, parentId: creator.id, balance: Number(referral.startingBalance || 0), resetAttempts: 0, resetWindowStartedAt: now(), passwordResetAttempts: 0, passwordResetWindowStartedAt: now(), createdAt: now(), lastLoginAt: null, registeredIp: ip, panelIp: null };
  db.users.push(user); referral.usedCount = Number(referral.usedCount || 0) + 1;
  if (user.balance > 0) transaction(creator, "REFERRAL_STARTING_BALANCE", user.balance, 0, user.balance, user.id, { referralId: referral.id, code: referral.code, role: user.role });
  audit(creator, "REGISTER_USER", "user", user.id, { ip, details: { referralId: referral.id, referralCode: referral.code, role: user.role } });
  save(); res.status(201).json({ success: true, message: "Account created successfully.", user: publicUser(user) });
});

const resetDeviceAttempts = new Map();
function allowResetDevice(ip, username) {
  const key = `${ip}:${username}`; const nowMs = Date.now(); const row = resetDeviceAttempts.get(key) || { started: nowMs, count: 0 };
  if (nowMs - row.started >= 15 * 60 * 1000) { row.started = nowMs; row.count = 0; }
  if (row.count >= 5) return false; row.count++; resetDeviceAttempts.set(key, row); return true;
}
app.post("/api/auth/reset-device", async (req, res) => {
  const username = normalizeUsername(req.body.username); const password = String(req.body.password || ""); const deviceId = sanitizeString(req.body.deviceId || "", 160); const ip = clientIp(req);
  if (!username || !password || !deviceId) return res.status(400).json({ success: false, code: "INVALID_REQUEST", message: "All fields required." });
  if (!allowResetDevice(ip, username)) return res.status(429).json({ success: false, code: "RESET_RATE_LIMIT", message: "Too many device reset attempts. Try again later." });
  const user = findUserByUsername(username);
  if (!user || !(await verifyPassword(password, user.passwordHash))) return res.status(401).json({ success: false, code: "RESET_FAILED", message: "Invalid credentials." });
  if (user.status !== STATUS.ACTIVE) return res.status(403).json({ success: false, code: "RESET_FAILED", message: "Account blocked." });
  if (user.role !== ROLE.OWNER && Number(user.panelDeviceResetCount || 0) >= MAX_PANEL_DEVICE_RESETS) return res.status(429).json({ success: false, code: "RESET_LIMIT_REACHED", message: "Limit reached." });
  const oldDeviceId = user.panelDeviceId || null; user.panelDeviceId = deviceId; user.panelIp = ip; user.panelDeviceResetCount = Number(user.panelDeviceResetCount || 0) + 1;
  db.sessions = db.sessions.filter(x => x.userId !== user.id);
  audit(user, "RESET_PANEL_DEVICE", "user", user.id, { ip, details: { oldDeviceId: oldDeviceId ? oldDeviceId.slice(0, 12) : null, newDeviceId: deviceId.slice(0, 12), used: user.panelDeviceResetCount, remaining: MAX_PANEL_DEVICE_RESETS - user.panelDeviceResetCount } });
  save(); res.json({ success: true, message: "Device reset successfully.", reset: { used: user.panelDeviceResetCount, remaining: Math.max(0, MAX_PANEL_DEVICE_RESETS - user.panelDeviceResetCount) } });
});

app.post("/api/auth/reset-password", auth, async (req, res) => {
  const currentPassword = String(req.body.currentPassword || "");
  const newPassword = String(req.body.newPassword || "");
  if (!(await verifyPassword(currentPassword, req.user.passwordHash))) return res.status(401).json({ success: false, message: "Current password is incorrect." });
  if (!validPassword(newPassword)) return res.status(400).json({ success: false, message: "Invalid password." });
  req.user.passwordHash = await hashPassword(newPassword);
  db.sessions = db.sessions.filter(x => x.userId !== req.user.id || x.id === req.session.id);
  audit(req.user, "PASSWORD_CHANGED", "user", req.user.id, { ip: clientIp(req) });
  save();
  res.json({ success: true, message: "Password changed successfully." });
});

app.get("/api/auth/reset-status", auth, (req, res) => {
  const user = req.user;
  const started = Date.parse(user.passwordResetWindowStartedAt || 0); const resetWindowMs = resetWindowForRole(user.role);
  if (!user.passwordResetWindowStartedAt || Date.now() - started >= resetWindowMs) return res.json({ success: true, used: 0, remaining: MAX_RESET_ATTEMPTS, window: resetWindowLabel(user.role) });
  const used = Number(user.passwordResetAttempts || 0);
  res.json({ success: true, used, remaining: Math.max(0, MAX_RESET_ATTEMPTS - used), windowStartedAt: user.passwordResetWindowStartedAt, window: resetWindowLabel(user.role) });
});

app.post("/api/auth/change-password", auth, async (req, res) => {
  const currentPassword = String(req.body.currentPassword || "");
  const newPassword = String(req.body.newPassword || "");
  if (!(await verifyPassword(currentPassword, req.user.passwordHash))) return res.status(401).json({ success: false, message: "Current password is incorrect." });
  if (!validPassword(newPassword)) return res.status(400).json({ success: false, message: "Invalid password." });
  req.user.passwordHash = await hashPassword(newPassword);
  db.sessions = db.sessions.filter(s => s.userId !== req.user.id || s.id === req.session.id);
  audit(req.user, "PASSWORD_CHANGED", "user", req.user.id, { ip: clientIp(req) }); save();
  res.json({ success: true, message: "Password changed successfully." });
});

