  key.key=nextKey; key.deviceLimit=deviceLimit; key.gamePackage=sanitizeString(req.body.gamePackage ?? key.gamePackage ?? "",200); key.ipLock=sanitizeString(req.body.ipLock ?? key.ipLock ?? "",120); key.geoLock=sanitizeString(req.body.geoLock ?? key.geoLock ?? "",120); key.status=status; if(status===KEY_STATUS.DELETED){key.deletedAt=key.deletedAt||now();db.devices=db.devices.filter(d=>d.keyId!==key.id)}
  audit(req.user,"UPDATE_KEY","key",key.id,{ip:clientIp(req),details:{key:key.key,deviceLimit:key.deviceLimit,status:key.status}}); save();
