/* ---------- Loader ---------- */
function loaderResponse(res, status, code, message, extra = {}) {
  return res.status(status).json({ success: false, code, message, requestId: res.req.requestId, ...extra });
}
function loaderSuccess(res, extra = {}) {
  return res.json({ success: true, requestId: res.req.requestId, ...extra });
}
function hashLoaderToken(token) { return crypto.createHash("sha256").update(String(token)).digest("hex"); }
function normalizeVersion(v) { return String(v || "0.0.0").trim().replace(/^v/i, ""); }
function compareVersions(a, b) {
  const aa = normalizeVersion(a).split(".").map(x => Number.parseInt(x, 10) || 0);
  const bb = normalizeVersion(b).split(".").map(x => Number.parseInt(x, 10) || 0);
  for (let i = 0; i < Math.max(aa.length, bb.length); i++) { const x = aa[i] || 0, y = bb[i] || 0; if (x !== y) return x > y ? 1 : -1; }
  return 0;
}
function loaderPackageForKey(key) { return sanitizeString(key?.gamePackage || db.settings.loaderTargetPackage || DEFAULT_TARGET_PACKAGE, 200); }
function loaderVersionPolicy(version) {
  const current = normalizeVersion(db.settings.loaderVersion || DEFAULT_LOADER_VERSION);
  const minimum = normalizeVersion(db.settings.loaderMinimumVersion || current);
  const supplied = normalizeVersion(version);
  return { current, minimum, supplied, compatible: compareVersions(supplied, minimum) >= 0, currentMatch: compareVersions(supplied, current) === 0 };
}
function loaderPublicConfig() {
  const s = db.settings || {};
  return {
    apiVersion: Number(s.loaderApiVersion || LOADER_API_VERSION),
    enabled: Boolean(s.loaderStatus) && s.systemOnline !== false,
    systemOnline: s.systemOnline !== false,
    maintenanceMessage: sanitizeString(s.maintenanceMsg || "Loader is temporarily under maintenance.", 1000),
    panelName: sanitizeString(s.panelName || "Lexi Loader", 100),
    targetPackage: sanitizeString(s.loaderTargetPackage || DEFAULT_TARGET_PACKAGE, 200),
    appNoticeEnabled: Boolean(s.appNoticeEnabled),
    appNotice: sanitizeString(s.appNotice || "", 2000),
    appNoticeType: sanitizeString(s.appNoticeType || "info", 30),
    features: { BT: Boolean(s.loaderFeatures?.BT), AIM: Boolean(s.loaderFeatures?.AIM), ESP: Boolean(s.loaderFeatures?.ESP), IPAD_VIEW: Boolean(s.loaderFeatures?.IPAD_VIEW) }
  };
}
function loaderVersionPayload() {
  const s = db.settings || {};
  return {
    apiVersion: Number(s.loaderApiVersion || LOADER_API_VERSION),
    currentVersion: normalizeVersion(s.loaderVersion || DEFAULT_LOADER_VERSION),
    minimumVersion: normalizeVersion(s.loaderMinimumVersion || s.loaderVersion || DEFAULT_LOADER_VERSION),
    updateRequired: Boolean(s.loaderUpdateRequired),
    updateUrl: sanitizeString(s.loaderUpdateUrl || "", 2000),
    updateSha256: String(s.loaderUpdateSha256 || "").trim().toLowerCase(),
    updateSize: Math.max(0, Number(s.loaderUpdateSize || 0)),
    updateNotes: sanitizeString(s.loaderUpdateNotes || "", 4000)
  };
}
function cleanupLoaderSessions() {
  const cutoff = Date.now();
  db.loaderSessions = (db.loaderSessions || []).filter(s => Date.parse(s.expiresAt || 0) > cutoff);
}
function createLoaderSession({ key, device, hwid, packageName, loaderVersion, ip }) {
  cleanupLoaderSessions();
  const token = randomToken(32);
  const createdAt = Date.now();
  db.loaderSessions.push({
    id: randomId("lsess"), tokenHash: hashLoaderToken(token), keyId: key.id, deviceId: device.id,
    hwid, packageName, loaderVersion: normalizeVersion(loaderVersion), ip,
    createdAt: new Date(createdAt).toISOString(), lastSeenAt: new Date(createdAt).toISOString(),
    expiresAt: new Date(createdAt + LOADER_SESSION_TTL_MS).toISOString()
  });
  return { token, expiresAt: new Date(createdAt + LOADER_SESSION_TTL_MS).toISOString() };
}
function getLoaderToken(req) {
  const authz = String(req.headers.authorization || "");
  if (!authz.toLowerCase().startsWith("bearer ")) return "";
  return authz.slice(7).trim();
}
function requireLoaderSession(req, res) {
  cleanupLoaderSessions();
  const token = getLoaderToken(req);
  if (!token) { loaderResponse(res, 401, "SESSION_INVALID", "Authorization Failed"); return null; }
  const tokenHash = hashLoaderToken(token);
  const session = db.loaderSessions.find(x => safeEqual(x.tokenHash, tokenHash));
  if (!session) { loaderResponse(res, 401, "SESSION_INVALID", "Authorization Failed"); return null; }
  if (Date.now() >= Date.parse(session.expiresAt || 0)) { db.loaderSessions = db.loaderSessions.filter(x => x.id !== session.id); save(); loaderResponse(res, 401, "SESSION_EXPIRED", "Session Expired"); return null; }
  if (session.ip && session.ip !== clientIp(req)) { loaderResponse(res, 403, "AUTHORIZATION_REVOKED", "Authorization Revoked"); return null; }
  session.lastSeenAt = now();
  req.loaderSession = session;
  req.loaderTokenHash = tokenHash;
  return session;
}
function findLoaderKey(session) { return db.keys.find(k => k.id === session.keyId); }
function checkLoaderAuthorization(session, packageName, loaderVersion, req) {
  if (!db.settings.loaderStatus || db.settings.systemOnline === false) return { status: 503, code: "LOADER_DISABLED", message: db.settings.maintenanceMsg || "Loader is temporarily under maintenance." };
  const key = findLoaderKey(session);
  if (!key || key.status === KEY_STATUS.DELETED) return { status: 404, code: "KEY_NOT_FOUND", message: "Invalid Key" };
  const status = keyStatus(key);
  if (status === KEY_STATUS.BLOCKED) return { status: 403, code: "KEY_BLOCKED", message: "Key Blocked" };
  if (status === KEY_STATUS.EXPIRED) return { status: 403, code: "KEY_EXPIRED", message: "Expired Key" };
  const policy = loaderVersionPolicy(loaderVersion);
  if (!policy.compatible || (db.settings.loaderUpdateRequired && !policy.currentMatch)) return { status: 426, code: "VERSION_UNSUPPORTED", message: "Please Update Loader", version: loaderVersionPayload() };
  const allowedPackage = loaderPackageForKey(key);
  if (allowedPackage && packageName !== allowedPackage) return { status: 403, code: "GAME_NOT_ALLOWED", message: "Application Not Allowed" };
  if (key.ipLock && key.ipLock !== clientIp(req)) return { status: 403, code: "IP_LOCKED", message: "IP Locked" };
  if (key.geoLock) { const geo = enforceGeoLock(req, key.geoLock); if (geo) return geo; }
  const device = db.devices.find(d => d.id === session.deviceId && d.keyId === key.id);
  if (!device || !safeEqual(device.hwid, session.hwid)) return { status: 403, code: "AUTHORIZATION_REVOKED", message: "Authorization Revoked" };
  const liveDevices = db.devices.filter(d => d.keyId === key.id);
  if (liveDevices.length > Number(key.deviceLimit || 1)) return { status: 403, code: "DEVICE_LIMIT_REACHED", message: "Device Limit Full" };
  return { key, device, policy };
}
function loaderLicenseSnapshot(key) {
  return { key: key.key, startedAt: key.startedAt || null, expiryAt: key.expiryAt || null, durationHours: Number(key.durationHours || 0), deviceLimit: Number(key.deviceLimit || 1), devicesUsed: db.devices.filter(d => d.keyId === key.id).length };
}

app.get("/api/loader/config", (req, res) => loaderSuccess(res, { loader: loaderPublicConfig(), pricing: db.pricing }));
app.get("/api/loader/version", (req, res) => loaderSuccess(res, { version: loaderVersionPayload() }));
app.get("/api/loader/manifest", (req, res) => loaderSuccess(res, { targetPackage: db.settings.loaderTargetPackage || DEFAULT_TARGET_PACKAGE, manifests: Array.isArray(db.settings.loaderFileManifests) ? db.settings.loaderFileManifests : [] }));

// Added  sync-mode endpoint for PostLaunchManager server synchronization
app.get("/api/loader/sync-mode", (req, res) => {
  const mode = sanitizeString(req.query.mode || "AIM", 50);
  return res.json({
    success: true,
    mode: mode,
    loaderVersion: db.settings.loaderVersion || "V-1.0",
    expiryText: null,
    time: now()
  });
});

const loaderVerifyAttempts = new Map();
function allowLoaderVerify(ip) {
  const nowMs = Date.now(); const row = loaderVerifyAttempts.get(ip) || { started: nowMs, count: 0 };
  if (nowMs - row.started >= 60 * 1000) { row.started = nowMs; row.count = 0; }
  if (row.count >= 60) return false; row.count++; loaderVerifyAttempts.set(ip, row); return true;
}
const loaderVerifyHandler = (req, res) => {
  const licenseKey = sanitizeString(req.body.key ?? req.body.license ?? req.body.licenseKey, 150);
  const hwid = sanitizeString(req.body.hwid ?? req.body.hardwareId ?? req.body.device_id, 300);
  const deviceName = sanitizeString(req.body.deviceName ?? req.body.device ?? req.body.device_name, 150);
  const packageName = sanitizeString(req.body.packageName ?? req.body.package ?? req.body.package_name, 200);
  const loaderVersion = normalizeVersion(req.body.loaderVersion ?? req.body.version ?? req.body.loader_version);
  const ip = clientIp(req);
  if (!allowLoaderVerify(ip)) return loaderResponse(res, 429, "RATE_LIMITED", "Too many verification requests. Try again later.");
  if (!db.settings.loaderStatus || db.settings.systemOnline === false) return loaderResponse(res, 503, "LOADER_DISABLED", db.settings.maintenanceMsg || "Loader is temporarily under maintenance.");
  if (!licenseKey || !hwid || !deviceName || !packageName || !loaderVersion) return loaderResponse(res, 400, "INVALID_REQUEST", "Required loader information is missing.");
  const policy = loaderVersionPolicy(loaderVersion);
  if (!policy.compatible) return loaderResponse(res, 426, "VERSION_UNSUPPORTED", "Please Update Loader", { version: loaderVersionPayload() });
  const key = db.keys.find(k => k.key === licenseKey);
  if (!key || key.status === KEY_STATUS.DELETED) return loaderResponse(res, 404, "KEY_NOT_FOUND", "Invalid Key");
  const status = keyStatus(key);
  if (status === KEY_STATUS.BLOCKED) return loaderResponse(res, 403, "KEY_BLOCKED", "Key Blocked");
  if (status === KEY_STATUS.EXPIRED) return loaderResponse(res, 403, "KEY_EXPIRED", "Expired Key");
  const allowedPackage = loaderPackageForKey(key);
  if (allowedPackage && packageName !== allowedPackage) return loaderResponse(res, 403, "GAME_NOT_ALLOWED", "Application Not Allowed");
  if (key.ipLock && key.ipLock !== ip) return loaderResponse(res, 403, "IP_LOCKED", "IP Locked");
  if (key.geoLock) { const geo = enforceGeoLock(req, key.geoLock); if (geo) return loaderResponse(res, geo.status, geo.code, geo.message); }
  let devices = db.devices.filter(d => d.keyId === key.id);
  let device = devices.find(d => safeEqual(d.hwid, hwid));
  const firstActivation = !key.startedAt;
  if (!device) {
    if (devices.length >= Number(key.deviceLimit || 1)) return loaderResponse(res, 403, "DEVICE_LIMIT_REACHED", "Device Limit Full");
    if (firstActivation) { const startedMs = Date.now(); key.startedAt = new Date(startedMs).toISOString(); key.expiryAt = new Date(startedMs + Number(key.durationHours || 0) * 60 * 60 * 1000).toISOString(); }
    device = { id: randomId("dev"), keyId: key.id, hwid, deviceName, ip, firstSeenAt: now(), lastSeenAt: now() };
    db.devices.push(device);
  } else {
    if (firstActivation) { const startedMs = Date.now(); key.startedAt = new Date(startedMs).toISOString(); key.expiryAt = new Date(startedMs + Number(key.durationHours || 0) * 60 * 60 * 1000).toISOString(); }
    device.lastSeenAt = now(); device.ip = ip; if (deviceName) device.deviceName = deviceName;
  }
  const session = createLoaderSession({ key, device, hwid, packageName, loaderVersion, ip });
  audit(null, "LOADER_VERIFY", "key", key.id, { ip, details: { requestId: req.requestId, deviceId: device.id, packageName, loaderVersion } });
  save();
  return loaderSuccess(res, { code: "VERIFIED", token: session.token, session: { expiresAt: session.expiresAt, ttlSeconds: Math.floor(LOADER_SESSION_TTL_MS / 1000) }, license: loaderLicenseSnapshot(key), loader: loaderPublicConfig(), version: loaderVersionPayload() });
};

app.post("/api/loader/verify", loaderVerifyHandler);
// Compatibility aliases: same authorization and license checks; no bypass.
app.post("/api/verify", loaderVerifyHandler);
app.post("/api/license/verify", loaderVerifyHandler);

app.post("/api/loader/feature_action", (req, res) => {
  const session = requireLoaderSession(req, res); if (!session) return;
  const selectedFeature = sanitizeString(req.body.selected_feature, 50).toUpperCase();
  const allowedFeatures = ["AIM", "BT", "ESP", "IPAD_VIEW"];
  if (!allowedFeatures.includes(selectedFeature)) return res.status(400).json({ success: false, reason: "Invalid feature." });
  if (!db.settings.loaderFeatures?.[selectedFeature]) return res.status(403).json({ success: false, reason: "Feature disabled." });
  const key = findLoaderKey(session);
  if (!key || keyStatus(key) !== KEY_STATUS.ACTIVE) return res.status(403).json({ success: false, reason: "License key is invalid or expired." });
  if (!safeEqual(session.hwid, sanitizeString(req.body.hwid || session.hwid, 300))) return res.status(403).json({ success: false, reason: "Device authorization mismatch." });
  const device = db.devices.find(d => d.id === session.deviceId && d.keyId === key.id && safeEqual(d.hwid, session.hwid));
  if (!device) return res.status(403).json({ success: false, reason: "Device authorization not found." });
  const authz = checkLoaderAuthorization(session, session.packageName, session.loaderVersion, req);
  if (authz.status) return res.status(authz.status).json({ success: false, reason: authz.message });
  key.active_hack = selectedFeature;
  key.hack_expiry = key.expiryAt || null;
  device.lastSeenAt = now();
  save();
  const prefixText = sanitizeString(db.settings.panelName || "Lexi Loader", 50);
  return res.json({ success: true, status: "SUCCESS", prefix_text: prefixText, selected_feature: key.active_hack });
});

app.post("/api/loader/launch", (req, res) => {
  const session = requireLoaderSession(req, res); if (!session) return;
  const packageName = sanitizeString(req.body.packageName || session.packageName, 200);
  const loaderVersion = normalizeVersion(req.body.loaderVersion || session.loaderVersion);
  const authz = checkLoaderAuthorization(session, packageName, loaderVersion, req);
  if (authz.status) { audit(null, "LOADER_LAUNCH_AUTH", "session", session.id, { ip: clientIp(req), details: { requestId: req.requestId, code: authz.code, packageName, loaderVersion } }); save(); return loaderResponse(res, authz.status, authz.code, authz.message, authz.version ? { version: authz.version } : {}); }
  const key = authz.key;
  session.lastSeenAt = now();
  audit(null, "LOADER_LAUNCH_AUTH", "key", key.id, { ip: clientIp(req), details: { requestId: req.requestId, result: "AUTHORIZED", packageName, loaderVersion } });
  save();
  return loaderSuccess(res, { code: "LAUNCH_AUTHORIZED", authorized: true, packageName, hack: key.active_hack || "ESP", hack_expiry: key.hack_expiry || null, license: loaderLicenseSnapshot(key), loader: loaderPublicConfig(), features: loaderPublicConfig().features });
});

app.post("/api/loader/logout", (req, res) => {
  const token = getLoaderToken(req);
  if (!token) return loaderSuccess(res, { code: "NO_SESSION" });
  const hash = hashLoaderToken(token);
  const before = db.loaderSessions.length;
  const session = db.loaderSessions.find(s => safeEqual(s.tokenHash, hash));
  db.loaderSessions = db.loaderSessions.filter(s => !safeEqual(s.tokenHash, hash));
  if (session) audit(null, "LOADER_LOGOUT", "session", session.id, { ip: clientIp(req), details: { requestId: req.requestId } });
  if (before !== db.loaderSessions.length) save();
  return loaderSuccess(res, { code: "LOGGED_OUT" });
});

app.post("/api/loader/heartbeat", (req, res) => {
  const session = requireLoaderSession(req, res); if (!session) return;
  const authz = checkLoaderAuthorization(session, session.packageName, session.loaderVersion, req);
  if (authz.status) return loaderResponse(res, authz.status, authz.code, authz.message, authz.version ? { version: authz.version } : {});
  session.lastSeenAt = now();
  session.expiresAt = new Date(Date.now() + LOADER_SESSION_TTL_MS).toISOString();
  save();
  return loaderSuccess(res, { code: "SESSION_ACTIVE", session: { expiresAt: session.expiresAt, ttlSeconds: Math.floor(LOADER_SESSION_TTL_MS / 1000) } });
});

app.post("/api/owner/loader-settings", auth, requireRoles(ROLE.OWNER), (req, res) => {
  const b = req.body || {};
  if (b.loaderStatus !== undefined) db.settings.loaderStatus = Boolean(b.loaderStatus);
  if (b.maintenanceMsg !== undefined) db.settings.maintenanceMsg = sanitizeString(b.maintenanceMsg, 1000);
  if (b.panelName !== undefined) db.settings.panelName = sanitizeString(b.panelName, 100);
  if (b.ipGeoLockEnabled !== undefined) db.settings.ipGeoLockEnabled = Boolean(b.ipGeoLockEnabled);
  if (b.loaderVersion !== undefined) db.settings.loaderVersion = normalizeVersion(b.loaderVersion);
  if (b.loaderMinimumVersion !== undefined) db.settings.loaderMinimumVersion = normalizeVersion(b.loaderMinimumVersion);
  if (b.loaderTargetPackage !== undefined) db.settings.loaderTargetPackage = sanitizeString(b.loaderTargetPackage, 200);
  if (b.loaderUpdateUrl !== undefined) db.settings.loaderUpdateUrl = sanitizeString(b.loaderUpdateUrl, 2000);
  if (b.loaderUpdateSha256 !== undefined) db.settings.loaderUpdateSha256 = String(b.loaderUpdateSha256 || "").trim().toLowerCase().slice(0, 128);
  if (b.loaderUpdateSize !== undefined) db.settings.loaderUpdateSize = Math.max(0, Number(b.loaderUpdateSize) || 0);
  if (b.loaderUpdateRequired !== undefined) db.settings.loaderUpdateRequired = Boolean(b.loaderUpdateRequired);
  if (b.loaderUpdateNotes !== undefined) db.settings.loaderUpdateNotes = sanitizeString(b.loaderUpdateNotes, 4000);
  if (b.loaderFeatures && typeof b.loaderFeatures === "object" && !Array.isArray(b.loaderFeatures)) db.settings.loaderFeatures = { ...db.settings.loaderFeatures, BT: Boolean(b.loaderFeatures.BT), AIM: Boolean(b.loaderFeatures.AIM), ESP: Boolean(b.loaderFeatures.ESP), IPAD_VIEW: Boolean(b.loaderFeatures.IPAD_VIEW) };
  if (Array.isArray(b.loaderFileManifests)) db.settings.loaderFileManifests = b.loaderFileManifests.slice(0, 100).map(x => ({ id: sanitizeString(x.id, 100), version: sanitizeString(x.version, 50), size: Math.max(0, Number(x.size) || 0), sha256: String(x.sha256 || "").trim().toLowerCase().slice(0, 128), required: Boolean(x.required), pathClass: sanitizeString(x.pathClass || "loader-owned", 50) }));
  audit(req.user, "UPDATE_LOADER_SETTINGS", "settings", "global", { ip: clientIp(req), details: { requestId: req.requestId, loaderVersion: db.settings.loaderVersion, minimumVersion: db.settings.loaderMinimumVersion, targetPackage: db.settings.loaderTargetPackage } });
  save();
  return res.json({ success: true, requestId: req.requestId, settings: loaderPublicConfig(), version: loaderVersionPayload(), manifests: db.settings.loaderFileManifests });
});

