app.get("/api/dashboard", auth, (req, res) => {
  const scope = getCreatorKeyScope(req.user); const visibleKeys = db.keys.filter(scope); const visibleUsers = db.users.filter(u => canViewUser(req.user, u));
  const counts = { activeKeys: visibleKeys.filter(k => keyStatus(k) === KEY_STATUS.ACTIVE).length, expiredKeys: visibleKeys.filter(k => keyStatus(k) === KEY_STATUS.EXPIRED).length, blockedKeys: visibleKeys.filter(k => keyStatus(k) === KEY_STATUS.BLOCKED).length, deletedKeys: visibleKeys.filter(k => keyStatus(k) === KEY_STATUS.DELETED).length, users: visibleUsers.length, admins: visibleUsers.filter(u => u.role === ROLE.ADMIN).length, resellers: visibleUsers.filter(u => u.role === ROLE.RESELLER).length };
  const ownTransactions = db.transactions.filter(t => req.user.role === ROLE.OWNER ? true : t.actorId === req.user.id || t.targetUserId === req.user.id );
  res.json({ success: true, user: publicUser(req.user), stats: { ...counts, balance: Number(req.user.balance || 0), totalVisibleBalance: visibleUsers.reduce((sum, u) => sum + Number(u.balance || 0), 0), referrals: db.referrals.filter(r => req.user.role === ROLE.OWNER || r.creatorId === req.user.id).length, transactions: ownTransactions.length }, settings: { loaderStatus: db.settings.loaderStatus, maintenanceMsg: db.settings.maintenanceMsg, panelName: db.settings.panelName, ipGeoLockEnabled: db.settings.ipGeoLockEnabled } });
});
app.get("/api/activity", auth, (req, res) => {
  let rows; if (req.user.role === ROLE.OWNER) { rows = [...db.auditLogs]; } else { const visible = new Set(db.users.filter(u => u.id === req.user.id || (u.parentId === req.user.id && u.role === ROLE.RESELLER)).map(u => u.id)); rows = db.auditLogs.filter(x => visible.has(x.actorId) || visible.has(x.targetId)); }
  res.json({ success: true, logs: rows.reverse().slice(0, 1000) });
});
app.get("/api/audit-logs", auth, requireRoles(ROLE.OWNER), (req, res) => {
  const q = sanitizeString(req.query.search, 100).toLowerCase(); let rows = [...db.auditLogs].reverse();
  if (q) rows = rows.filter(x => String(x.actorUsername).toLowerCase().includes(q) || String(x.action).toLowerCase().includes(q) || String(x.targetId || "").toLowerCase().includes(q) );
  res.json({ success: true, logs: rows.slice(0, 1000) });
});
app.get("/api/transactions", auth, (req, res) => {
  let rows; if (req.user.role === ROLE.OWNER) { rows = [...db.transactions]; } else { const visibleUsers = new Set(db.users.filter(u => u.id === req.user.id || (u.parentId === req.user.id && u.role === ROLE.RESELLER)).map(u => u.id)); rows = db.transactions.filter(t => visibleUsers.has(t.actorId) || visibleUsers.has(t.targetUserId)); }
  res.json({ success: true, transactions: rows.reverse().slice(0, 1000) });
});
app.get("/api/settings", auth, (req, res) => {
  if (req.user.role === ROLE.OWNER) return res.json({ success: true, settings: db.settings, role: req.user.role });
  res.json({ success: true, settings: { username: req.user.username, usernameChangeCount: Number(req.user.usernameChangeCount || 0), usernameChangeRemaining: req.user.role === ROLE.OWNER ? null : Math.max(0, 1 - Number(req.user.usernameChangeCount || 0)), passwordResetAttempts: Number(req.user.passwordResetAttempts || 0), passwordResetRemaining: req.user.role === ROLE.OWNER ? null : Math.max(0, MAX_RESET_ATTEMPTS - Number(req.user.passwordResetAttempts || 0)), passwordResetWindow: req.user.role === ROLE.OWNER ? "unlimited" : resetWindowLabel(req.user.role), theme: "local" }, role: req.user.role });
});
app.post("/api/profile/update", auth, (req, res) => {
  const username = normalizeUsername(req.body.username); if (!validUsername(username)) return res.status(400).json({ success: false, message: "Invalid." });
  if (username !== req.user.username) {
    if (Number(req.user.usernameChangeCount || 0) >= 1) return res.status(429).json({ success: false, message: "Limit reached." });
    if (findUserByUsername(username)) return res.status(409).json({ success: false, message: "Exists." });
    req.user.username = username; req.user.usernameChangeCount = Number(req.user.usernameChangeCount || 0) + 1; audit(req.user, "USERNAME_CHANGED", "user", req.user.id, { ip: clientIp(req), details: { username } }); save();
  }
  res.json({ success: true, user: publicUser(req.user), usernameChangeRemaining: Math.max(0, 1 - Number(req.user.usernameChangeCount || 0)) });
});
app.post("/api/settings/update", auth, requireRoles(ROLE.OWNER), (req, res) => {
  const allowed = [ "panelName", "panelVersion", "supportLink", "sessionTimeoutHours", "resetLimit", "resetWindowHours", "ipGeoLockEnabled", "systemOnline", "onlineMessage", "appNotice", "appNoticeType", "appNoticeEnabled" ];
  for (const field of allowed) {
    if (req.body[field] === undefined) continue;
    if (["sessionTimeoutHours", "resetLimit", "resetWindowHours"].includes(field)) {
      const n = Number(req.body[field]); if (!Number.isFinite(n) || n <= 0) return res.status(400).json({ success: false, message: `Invalid.` });
      if (field === "sessionTimeoutHours" && !ALLOWED_SESSION_HOURS.includes(Math.floor(n))) return res.status(400).json({ success: false, message: "Invalid timeout." });
      db.settings[field] = Math.floor(n);
    } else if (["ipGeoLockEnabled", "systemOnline", "appNoticeEnabled"].includes(field)) { db.settings[field] = Boolean(req.body[field]); } else { db.settings[field] = sanitizeString(req.body[field], field === "supportLink" ? 500 : 150); }
  }
  audit(req.user, "UPDATE_SETTINGS", "settings", "global", { ip: clientIp(req), details: { fields: allowed.filter(x => req.body[x] !== undefined) } }); save(); res.json({ success: true, settings: db.settings });
});
app.post("/api/settings/loader", auth, requireRoles(ROLE.OWNER), (req, res) => {
  const b = req.body || {};
  if (b.enabled !== undefined) db.settings.loaderStatus = Boolean(b.enabled);
  if (b.message !== undefined) db.settings.maintenanceMsg = sanitizeString(b.message, 1000);
  if (b.loaderStatus !== undefined) db.settings.loaderStatus = Boolean(b.loaderStatus);
  if (b.maintenanceMsg !== undefined) db.settings.maintenanceMsg = sanitizeString(b.maintenanceMsg, 1000);
  if (b.loaderVersion !== undefined) db.settings.loaderVersion = normalizeVersion(b.loaderVersion);
  if (b.loaderMinimumVersion !== undefined) db.settings.loaderMinimumVersion = normalizeVersion(b.loaderMinimumVersion);
  if (b.loaderTargetPackage !== undefined) db.settings.loaderTargetPackage = sanitizeString(b.loaderTargetPackage, 200);
  if (b.loaderUpdateUrl !== undefined) db.settings.loaderUpdateUrl = sanitizeString(b.loaderUpdateUrl, 2000);
  if (b.loaderUpdateSha256 !== undefined) db.settings.loaderUpdateSha256 = String(b.loaderUpdateSha256 || "").trim().toLowerCase().slice(0,128);
  if (b.loaderUpdateSize !== undefined) db.settings.loaderUpdateSize = Math.max(0, Number(b.loaderUpdateSize) || 0);
  if (b.loaderUpdateRequired !== undefined) db.settings.loaderUpdateRequired = Boolean(b.loaderUpdateRequired);
  if (b.loaderUpdateNotes !== undefined) db.settings.loaderUpdateNotes = sanitizeString(b.loaderUpdateNotes, 4000);
  audit(req.user, "UPDATE_LOADER_SETTINGS", "settings", "global", { ip: clientIp(req), details: { requestId: req.requestId, loaderStatus: db.settings.loaderStatus } });
  save();
  res.json({ success: true, requestId: req.requestId, settings: loaderPublicConfig(), version: loaderVersionPayload() });
});
app.get("/api/pricing", auth, requireRoles(ROLE.OWNER, ROLE.ADMIN, ROLE.RESELLER), (req, res) => { res.json({ success: true, pricing: db.pricing }); });
app.post("/api/pricing/update", auth, requireRoles(ROLE.OWNER), (req, res) => {
  const incoming = req.body.pricing; if (!incoming || typeof incoming !== "object" || Array.isArray(incoming)) return res.status(400).json({ success: false, message: "Invalid." });
  const next = {};
  for (const key of Object.keys(PRICING)) {
    const row = incoming[key]; if (!row) return res.status(400).json({ success: false, message: `Missing ${key}.` });
    const hours = Number(row.hours); const price = Number(row.price); const label = sanitizeString(row.label || key, 60);
    if (!Number.isFinite(hours) || hours <= 0 || !Number.isFinite(price) || price < 0) return res.status(400).json({ success: false, message: `Invalid.` });
    next[key] = { label, hours, price: Number(price.toFixed(2)) };
  }
  db.pricing = next; audit(req.user, "UPDATE_PRICING", "pricing", "global", { ip: clientIp(req), details: next }); save(); res.json({ success: true, pricing: db.pricing });
});
app.post("/api/owner/enter-user/:id", auth, requireRoles(ROLE.OWNER), (req, res) => {
  const target = findUserById(req.params.id); if (!target || target.id === req.user.id) return res.status(404).json({ success: false, message: "Not found." });
  if (target.status !== STATUS.ACTIVE) return res.status(403).json({ success: false, message: "Blocked." });
  const ownerSessionId = req.session.id;
  const token = createSession(target, req, false, true);
  setSessionCookie(res, token, DEFAULT_SESSION_TIMEOUT_MS);
  setOwnerSessionCookie(res, ownerSessionId);
  audit(req.user, "OWNER_ENTER_USER_PANEL", "user", target.id, { ip: clientIp(req), details: { supportSession: true } }); save();
  res.json({ success: true, user: publicUser(target), supportSession: true });
});
app.post("/api/owner/return", auth, requireRoles(ROLE.RESELLER, ROLE.ADMIN, ROLE.OWNER), (req, res) => {
  if (!req.session.supportSession) return res.status(400).json({ success: false, message: "Not in a support session." });
  const cookies = parseCookies(req); const ownerSessionId = cookies.lexi_owner_session || "";
  if (!ownerSessionId || !/^[A-Za-z0-9_-]{8,120}$/.test(ownerSessionId)) return res.status(401).json({ success: false, message: "Owner session unavailable." });
  const ownerSession = db.sessions.find(s => s.id === ownerSessionId);
  const owner = ownerSession ? findUserById(ownerSession.userId) : null;
  if (!ownerSession || !owner || owner.role !== ROLE.OWNER || !isActiveUser(owner)) return res.status(401).json({ success: false, message: "Owner session invalid." });
  db.sessions = db.sessions.filter(s => s.id !== req.session.id);
  clearOwnerSessionCookie(res);
  const restoredToken = randomToken(32);
  ownerSession.tokenHash = hashPanelToken(restoredToken);
  ownerSession.lastActivityAt = now();
  ownerSession.expiresAt = new Date(Date.now() + DEFAULT_SESSION_TIMEOUT_MS).toISOString();
  setSessionCookie(res, restoredToken, DEFAULT_SESSION_TIMEOUT_MS);
  audit(owner, "OWNER_RETURN_FROM_USER_PANEL", "user", req.user.id, { ip: clientIp(req), details: { supportSession: false } }); save();
  res.json({ success: true, user: publicUser(owner) });
});

