app.get(/^\/Register$/i, (req, res) => res.type("html").send(PANEL_HTML));
app.get(/^\/(Dashboard|Generate-Keys|Manage-Keys|Manage-Key|Users|Referrals|Transactions|Activity|Audit-Logs|Settings|Online|Loader)(?:\/.*)?$/i, (req, res) => res.type("html").send(PANEL_HTML));

/* ---------- Error Handling ---------- */
app.use("/api", (req, res) => { res.status(404).json({ success: false, message: "API endpoint not found." }); });
app.use((err, req, res, next) => { console.error(err); if (res.headersSent) return next(err); res.status(500).json({ success: false, message: "Internal server error." }); });

setInterval(() => {
  try {
    const before = db.loaderSessions.length;
    const sessionBefore = db.sessions.length;
    cleanupLoaderSessions();
    db.sessions = db.sessions.filter(s => isActiveUser(findUserById(s.userId)) && Date.parse(s.expiresAt || 0) > Date.now());
    cleanRateLimits();
    if (before !== db.loaderSessions.length || sessionBefore !== db.sessions.length) save();
  } catch (err) { console.error("[Lexi Loader] maintenance sweep failed:", err.message); }
}, 5 * 60 * 1000).unref?.();

let shuttingDown = false;
function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;
  try { save(); } catch {}
  releaseDatabaseLock();
  process.exit(0);
}
process.once("SIGINT", () => shutdown("SIGINT"));
process.once("SIGTERM", () => shutdown("SIGTERM"));
process.once("exit", releaseDatabaseLock);

app.listen(PORT, () => {
  console.log(`Lexi Loader backend running on port ${PORT}`);
  console.log(`Database: ${DB_FILE}`);
});
